modules.splice(0,modules.length,...[modules[0],modules[1],modules[5],modules[4],modules[6],modules[7],modules[8],modules[9],modules[10],modules[11],modules[2],modules[3],modules[12]]);
const exercises={
 python:[{name:'1 · Compute a simple return',prompt:'01 / PYTHON BASICS',brief:'Calculate a simple price return. Returns describe relative change; they help compare moves across price levels.',body:'Use the prices below to compute the simple return: (end − start) / start. Print the answer as a percentage.',code:'start_price = 50.08\nend_price = 50.14\n\n# Calculate and print the simple return\nreturn_pct = (end_price - start_price) / start_price\nprint(f"Return: {return_pct:.4%}")',test:(out)=>({ok:out.includes('0.1198%')||out.includes('0.1199%'),label:'Return calculation is close to 0.1199%.'})},{name:'2 · Inspect a price series',prompt:'01 / DATA INSPECTION',brief:'Summarize this tiny synthetic price series before deciding what it means. Inspection helps catch surprises early.',body:'Print the observation count, minimum, and maximum. These checks confirm what data actually reached your analysis.',code:'prices = [50.08, 50.12, 50.10, 50.17, 50.14]\n\n# Inspect before you analyze\nprint("Count:", len(prices))\nprint("Min:", min(prices))\nprint("Max:", max(prices))',test:(out)=>({ok:out.includes('Count: 5')&&out.includes('Min: 50.08')&&out.includes('Max: 50.17'),label:'Count, minimum, and maximum are all present.'})},{name:'3 · Estimate net return',prompt:'03 / TRADING COSTS',brief:'Gross performance is not what reaches your account. Subtract the estimated spread, slippage, and fees.',body:'Compute net return from an 18 bps gross move after the costs below. One basis point is 0.01%.',code:'gross_return = 0.0018\nspread_cost = 0.0006\nslippage = 0.0003\nfees = 0.0001\n\n# Subtract all trading costs\nnet_return = gross_return - spread_cost - slippage - fees\nprint(f"Net: {net_return:.2%}")',test:(out)=>({ok:out.includes('0.08%'),label:'Net return is 8 basis points, after all costs.'})}],
 sql:[{name:'1 · Filter eligible observations',prompt:'02 / SQL FILTERING',brief:'Filter a synthetic price table to one symbol, then sort chronologically. The SQL runtime creates the tiny practice table for you.',body:'Keep the row filter explicit and order by date. The example schema is daily_prices(symbol, date, open, close, volume).',code:"SELECT symbol, date, close, volume\nFROM daily_prices\nWHERE symbol = 'ALFA' AND volume > 1000000\nORDER BY date;",test:(out)=>({ok:out.includes('ALFA')&&out.includes('date'),label:'Filtered rows returned with the requested columns.'})},{name:'2 · Count observations by symbol',prompt:'02 / SQL AGGREGATION',brief:'Before comparing symbols, check how many observations each one has. Imbalanced samples can distort a comparison.',body:'Group by symbol and count rows. Label the count with AS so the output is easy to read.',code:'SELECT symbol, COUNT(*) AS observations\nFROM daily_prices\nGROUP BY symbol\nORDER BY symbol;',test:(out)=>({ok:out.includes('observations'),label:'Grouped observation counts returned.'})},{name:'3 · Summarize trading volume',prompt:'02 / SQL AGGREGATION',brief:'Aggregate daily activity per symbol. Averages need context; compare the underlying distributions in real research.',body:'Return each symbol and its average volume. Use a clear column alias.',code:'SELECT symbol, AVG(volume) AS average_volume\nFROM daily_prices\nGROUP BY symbol\nORDER BY average_volume DESC;',test:(out)=>({ok:out.includes('average_volume'),label:'Average volume by symbol returned.'})}],
 javascript:[{name:'1 · Calculate a price return',prompt:'STUDIO / JAVASCRIPT',brief:'Use a compact JavaScript calculation as a second way to check your arithmetic.',body:'Compute the simple return and print the percentage.',code:'const start = 50.08;\nconst end = 50.14;\nconst result = (end - start) / start;\nconsole.log(`Return: ${(result * 100).toFixed(4)}%`);',test:(out)=>({ok:out.includes('0.1199')||out.includes('0.1198'),label:'Return calculation is close to 0.1199%.'})},{name:'2 · Inspect a series',prompt:'STUDIO / JAVASCRIPT',brief:'Inspect the values before forming an explanation about them.',body:'Print the count, minimum, and maximum of the synthetic prices.',code:'const prices = [50.08, 50.12, 50.10, 50.17, 50.14];\nconsole.log("Count:", prices.length);\nconsole.log("Min:", Math.min(...prices));\nconsole.log("Max:", Math.max(...prices));',test:(out)=>({ok:out.includes('Count: 5')&&out.includes('50.08')&&out.includes('50.17'),label:'The requested summary statistics are present.'})},{name:'3 · Net after costs',prompt:'STUDIO / TRADING COSTS',brief:'Check the same trading-cost arithmetic in JavaScript.',body:'Compute gross return less spread, slippage, and fees.',code:'const gross = 0.0018;\nconst spread = 0.0006;\nconst slippage = 0.0003;\nconst fees = 0.0001;\nconst net = gross - spread - slippage - fees;\nconsole.log("Net:", (net * 100).toFixed(2) + "%");',test:(out)=>({ok:out.includes('0.08%'),label:'Net return is 8 basis points.'})}]};
const defaultState={done:[],goal:30,sessions:0,minutes:0,todayMinutes:0,recall:0,streak:0,lastDay:null,scenario:null,attempts:{},reviews:{},skills:{},projects:{},interviewNotes:{},scenarioNotes:{},scenarioCases:{},role:'research-architect',curriculumVersion:2};let rawState={};try{rawState=JSON.parse(localStorage.getItem('fieldnotes-state')||'{}')}catch{}let state={...defaultState,...rawState};if(!Number.isInteger(rawState.curriculumVersion)||rawState.curriculumVersion<2){const map={0:0,1:1,2:10,3:11,4:3,5:2,6:4,7:5,8:6,9:7,10:8,11:9,12:12};state.done=(state.done||[]).map(id=>{let [m,l]=id.split('-').map(Number);return `${map[m]??m}-${l}`});state.curriculumVersion=2}state.codingCompleted??=[];let selectedEditors={python:0,sql:0,javascript:0};let currentEditor='python';let scenarioChoice=null;let sessionCounted=false;let lessonPractice=false;let toastTimer;let accountUser=null;let cloudEnabled=false;
exercises.python.push(...(window.CODING_EXERCISES?.python||[]));exercises.sql.push(...(window.CODING_EXERCISES?.sql||[]));
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];function save(){let key=accountUser?'fieldnotes-state:'+accountUser.email.toLowerCase():'fieldnotes-state';localStorage.setItem(key,JSON.stringify(state));renderProgress();window.dispatchEvent(new CustomEvent('fieldnotes:progress-saved',{detail:{state,account:accountUser}}))}function allLessons(){return modules.flatMap((m,mi)=>m.lessons.map((l,li)=>({...l,mi,li,id:`${mi}-${li}`})))}function getLesson(id){return allLessons().find(l=>l.id===id)}function nextLesson(){return allLessons().find(l=>!state.done.includes(l.id))||allLessons().at(-1)}function showToast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}function renderProgress(){const lessons=allLessons(),done=lessons.filter(l=>state.done.includes(l.id)).length,p=Math.round(done/lessons.length*100),next=nextLesson();$('#overall-progress').style.width=p+'%';$('#progress-summary').textContent=`${done} of ${lessons.length} lessons`;$('#nav-progress').textContent=String(Math.min(done+1,lessons.length)).padStart(2,'0');$('#curriculum-percent').textContent=p+'%';$('#curriculum-progress-text').textContent=`${done} of ${lessons.length} lessons complete`;$('#streak-top').textContent=state.streak||0;$('#stat-sessions').innerHTML=`${state.sessions}<span> sessions</span>`;$('#stat-recall').innerHTML=`${state.recall}<span> concepts</span>`;$('#stat-hours').innerHTML=`${(state.minutes/60).toFixed(state.minutes%60?1:0)}<span> hrs</span>`;$('#goal-value').textContent=state.goal;$('#today-minutes').textContent=`${Math.min(state.todayMinutes||0,state.goal)} / ${state.goal} min`;$('#goal-progress').style.width=Math.min(100,(state.todayMinutes||0)/state.goal*100)+'%';$$('[data-goal]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.goal)===state.goal));$('#next-title').textContent=next.title;$('#next-desc').textContent=next.lead;$('#next-module-label').textContent='MODULE '+String(next.mi+1).padStart(2,'0');$('#next-language').textContent=`${next.lang.toUpperCase()} · ${next.topic.toUpperCase()}`;$('#next-mins').textContent=next.mins;renderModules();window.renderLearningPanels?.()}
function renderModules(){const root=$('#module-list');root.innerHTML='';modules.forEach((m,mi)=>{const done=m.lessons.filter((_,li)=>state.done.includes(`${mi}-${li}`)).length,priorDone=mi===0||modules.slice(0,mi).every((x,pi)=>x.lessons.every((_,li)=>state.done.includes(`${pi}-${li}`)));const card=document.createElement('article');card.className='module-card';card.innerHTML=`<header class="module-head"><div class="module-icon">${m.icon}</div><div><h2>${m.title}</h2><p>${m.description}</p></div><span>${done}/${m.lessons.length} COMPLETE</span></header><div class="lesson-list">${m.lessons.map((l,li)=>{let isDone=state.done.includes(`${mi}-${li}`),unlocked=priorDone&&(li===0||m.lessons.slice(0,li).every((_,p)=>state.done.includes(`${mi}-${p}`)));return `<div class="lesson-row"><span class="lesson-state ${isDone?'done':''}">${isDone?'✓':unlocked?String(li+1).padStart(2,'0'):'⌑'}</span><div class="lesson-info"><b>${l.title}</b><small>${l.topic} · ${l.mins} min ${unlocked?'':'· Complete earlier modules to unlock'}</small></div><span class="lesson-duration">${l.lang}</span><button class="lesson-open" data-lesson="${mi}-${li}" ${unlocked?'':'disabled'}>${isDone?'Review':unlocked?'Begin':'Locked'} ${unlocked?'→':''}</button></div>`}).join('')}</div>`;root.appendChild(card)});$$('[data-lesson]').forEach(b=>b.addEventListener('click',()=>openLesson(b.dataset.lesson)))}
function lessonReferences(lesson){const reference=window.CURRICULUM_REFERENCES?.[lesson.mi],readings=window.CURRICULUM_READINGS?.[lesson.mi]||[];if(!reference&&!readings.length)return'';const items=[...(reference?.items||[]).map(([title,url])=>({title,url})),...readings.map(title=>({title,url:''}))];return `<aside class="lesson-references"><span class="section-kicker">READING &amp; RESEARCH PRACTICE</span>${reference?.technique?`<p><b>Try this technique:</b> ${escapeHTML(reference.technique)}</p>`:''}<ul>${items.map(item=>`<li>${item.url?`<a href="${escapeHTML(item.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(item.title)} ↗</a>`:escapeHTML(item.title)}</li>`).join('')}</ul><small>References are optional depth. Apply the technique, record what you learned, and verify assumptions in context.</small></aside>`}
function openLesson(id){const l=getLesson(id);if(!l)return;$('#lesson-progress-label').textContent=`MODULE ${String(l.mi+1).padStart(2,'0')} / LESSON ${String(l.li+1).padStart(2,'0')}`;$('#lesson-content').dataset.lesson=id;$('#lesson-content').innerHTML=`<div class="lesson-eyebrow">${l.topic.toUpperCase()} · ${l.mins} MIN</div><h2>${l.title.split(' ').slice(0,-1).join(' ')} <span>${l.title.split(' ').at(-1)}.</span></h2><p class="lesson-lead">${l.lead}</p><h3>A way to think about it</h3><p>${l.body}</p><div class="lesson-callout">${l.callout}</div>${lessonReferences(l)}<h3>Make it concrete</h3><pre>${escapeHTML(l.code)}</pre><button class="outline-button" data-copy-practice="${l.id}">Open this example in the studio ↗</button><h3>Quick recall</h3><p>${l.quiz}</p><div class="lesson-check">${l.answers.map((a,i)=>`<button class="lesson-answer" data-answer="${i}">${String.fromCharCode(65+i)} &nbsp; ${a}</button>`).join('')}</div><div class="quiz-feedback" id="quiz-feedback"></div><div class="lesson-actions"><span>Each correct answer strengthens your recall.</span><button class="button-primary" id="mark-complete" disabled>${state.done.includes(l.id)?'Lesson complete ✓':'Complete lesson'} <span>↗</span></button></div>`;$('#lesson-overlay').hidden=false;let choice=-1;$$('.lesson-answer').forEach(btn=>btn.addEventListener('click',()=>{choice=Number(btn.dataset.answer);let skill=/sql/i.test(l.lang)?'SQL':/probab/i.test(l.topic)?'Probability':/stat/i.test(l.topic)?'Statistics':/linear|optim/i.test(l.topic)?'Linear algebra':/algorithm/i.test(l.topic)?'Algorithms':/time.series/i.test(l.topic)?'Time series':/microstructure|execution/i.test(l.topic)?'Microstructure':/system/i.test(l.topic)?'Systems':'Python';let correct=choice===l.correct;window.learningRecordSkill?.(skill,correct,l.topic||l.title,l.id);window.learningScheduleReview?.('lesson:'+l.id,skill,correct,l.topic||l.title);window.Fieldnotes.state.attempts['lesson:'+l.id]=(window.Fieldnotes.state.attempts['lesson:'+l.id]||0)+1;window.Fieldnotes.save();$$('.lesson-answer').forEach(b=>b.classList.toggle('selected',b===btn));let fb=$('#quiz-feedback');fb.classList.add('show');if(correct){btn.classList.add('correct');fb.textContent='That’s right. '+l.ex;$('#mark-complete').disabled=false}else{btn.classList.add('selected');fb.textContent='Not quite. Revisit the explanation above and try again.'}}));$('#mark-complete').addEventListener('click',()=>{if(!state.done.includes(l.id)){state.done.push(l.id);state.recall++;state.sessions++;state.minutes+=l.mins;setActivityDay();state.todayMinutes+=l.mins;save();showToast('Lesson complete · your progress is saved.')}$('#lesson-overlay').hidden=true});$('[data-copy-practice]')?.addEventListener('click',()=>{selectView('studio');const item=exercises[l.lang.toLowerCase()]?.[0];if(item){let idx=exercises[l.lang.toLowerCase()].findIndex(x=>x.code===l.code);if(idx>=0)selectedEditors[l.lang.toLowerCase()]=idx;setEditor(l.lang.toLowerCase());$('#code-input').value=l.code;updateLineNums()}$('#lesson-overlay').hidden=true})}
function escapeHTML(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function localDateKey(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}function setActivityDay(){let now=new Date(),today=localDateKey(now);if(state.lastDay!==today){let yd=new Date(now);yd.setDate(yd.getDate()-1);let yesterday=localDateKey(yd);state.streak=state.lastDay===yesterday?(state.streak||0)+1:1;state.lastDay=today;state.todayMinutes=0}}
