function renderBrief(){let ex=exercises[currentEditor][selectedEditors[currentEditor]];$('#exercise-brief').innerHTML=`<span class="section-kicker">THE TASK</span><h3>${ex.name.replace(/^\d · /,'')}</h3><p>${ex.body}</p><ul><li>Write your solution in the editor and run it.</li><li>Read the output, then explain what it tells you.</li><li>Explore the starter code and test a changed input.</li></ul>`}
function renderStudioProgress(){let list=exercises[currentEditor],index=selectedEditors[currentEditor],done=state.codingCompleted||[],key=`${currentEditor}:${list[index].name}`,label=$('#studio-progress-label'),prev=$('#exercise-previous'),next=$('#exercise-next');if(label)label.textContent=`${list.filter(ex=>done.includes(`${currentEditor}:${ex.name}`)).length} of ${list.length} checks passed`;if(prev)prev.disabled=index===0;if(next){next.disabled=!done.includes(key);next.textContent=index<list.length-1?'Next exercise →':currentEditor==='python'?'Continue to SQL →':currentEditor==='sql'?'Continue to JavaScript →':'Continue learning →'}}function moveExercise(direction){let list=exercises[currentEditor],index=selectedEditors[currentEditor],current=list[index],passed=(state.codingCompleted||[]).includes(`${currentEditor}:${current.name}`);if(direction<0){if(index>0){$('#exercise-select').value=String(index-1);$('#exercise-select').dispatchEvent(new Event('change',{bubbles:true}))}return}if(!passed){showToast('Pass this exercise check to unlock your next step.');return}if(index<list.length-1){$('#exercise-select').value=String(index+1);$('#exercise-select').dispatchEvent(new Event('change',{bubbles:true}));return}if(currentEditor==='python'){$('.editor-tab[data-editor="sql"]').click();return}if(currentEditor==='sql'){$('.editor-tab[data-editor="javascript"]').click();return}selectView('curriculum');openLesson(nextLesson().id)}function updateLineNums(){let n=Math.max(7,$('#code-input').value.split('\n').length);$('#line-numbers').innerHTML=Array.from({length:n},(_,i)=>i+1).join('<br>')}
