const pyScript='https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js',sqlScript='https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/sql-wasm.js';let pyReady=null,sqlReady=null;function loadScript(src){return new Promise((resolve,reject)=>{let s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(new Error('Could not load the browser runtime. Check your connection and try again.'));document.head.appendChild(s)})}async function runPython(code){if(!pyReady)pyReady=(async()=>{if(!window.loadPyodide)await loadScript(pyScript);return window.loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v0.27.7/full/'})})();let py=await pyReady;py.runPython('import sys\nfrom io import StringIO\n_output = StringIO()\n_old_stdout = sys.stdout\nsys.stdout = _output');try{py.runPython(code);return py.runPython('_output.getvalue()')||'(Code ran successfully; no output. Use print() to inspect results.)'}finally{py.runPython('sys.stdout = _old_stdout')}}async function runSQL(code){if(!sqlReady)sqlReady=(async()=>{if(!window.initSqlJs)await loadScript(sqlScript);return window.initSqlJs({locateFile:f=>'https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/'+f})})();let SQL=await sqlReady,db=new SQL.Database();db.run('CREATE TABLE daily_prices (symbol TEXT, date TEXT, open REAL, close REAL, volume INTEGER)');db.run("INSERT INTO daily_prices VALUES ('ALFA','2026-09-28',50.08,50.12,1320000),('ALFA','2026-09-29',50.12,50.10,1540000),('ALFA','2026-09-30',50.10,50.17,1210000),('BETA','2026-09-28',82.1,82.4,890000),('BETA','2026-09-29',82.4,81.9,1740000),('BETA','2026-09-30',81.9,82.2,2100000)");let res=db.exec(code);if(!res.length)return 'Query ran successfully; no rows returned.';let{columns,values}=res[0];let rows=[columns.join(' | '),...values.map(r=>r.map(x=>x===null?'NULL':String(x)).join(' | '))];return rows.join('\n')}
function runJS(code){return new Promise((resolve,reject)=>{if(!window.Worker||!window.URL?.createObjectURL){reject(new Error('The JavaScript sandbox is unavailable in this browser. Please use a modern browser over HTTP or HTTPS.'));return}let source=`const logs=[];const fmt=v=>{try{return typeof v==='string'?v:JSON.stringify(v)}catch(e){return String(v)}};const c={log:(...a)=>logs.push(a.map(fmt).join(' ')),warn:(...a)=>logs.push('Warning: '+a.map(fmt).join(' ')),error:(...a)=>logs.push('Error: '+a.map(fmt).join(' ')),table:v=>logs.push(JSON.stringify(v,null,2))};try{new Function('console','postMessage',\"\\\"use strict\\\";\\n\"+${JSON.stringify(code)})(c,postMessage);postMessage({type:'done',out:logs.join('\\n')||'(Code ran successfully; no output. Use console.log() to inspect results.)'})}catch(e){postMessage({type:'error',message:e.name+': '+e.message})}`;let blob=new Blob([source],{type:'text/javascript'}),url=URL.createObjectURL(blob),worker=new Worker(url),timer=setTimeout(()=>{worker.terminate();URL.revokeObjectURL(url);reject(new Error('Execution exceeded 1.5 seconds and was stopped. Check for an unintended loop.'))},1500);worker.onmessage=e=>{if(e.data?.type==='error'){clearTimeout(timer);worker.terminate();URL.revokeObjectURL(url);reject(new Error(e.data.message))}else if(e.data?.type==='done'){clearTimeout(timer);worker.terminate();URL.revokeObjectURL(url);resolve(e.data.out)}};worker.onerror=e=>{clearTimeout(timer);worker.terminate();URL.revokeObjectURL(url);reject(new Error(e.message||'The JavaScript worker could not run this code.'))}})}
async function runCode(){let btn=$('#run-code'),status=$('#runtime-status'),consoleBox=$('#console-output'),testBox=$('#test-results'),code=$('#code-input').value;btn.disabled=true;btn.innerHTML='<span>◌</span> Running';status.innerHTML='<span class="status-dot"></span> Preparing runtime…';consoleBox.textContent='Starting your practice environment…';try{let exercise=exercises[currentEditor][selectedEditors[currentEditor]],runSource=currentEditor==='python'&&exercise.testCode?code+"\n"+exercise.testCode:code;let out=currentEditor==='python'?await runPython(runSource):currentEditor==='sql'?await runSQL(code):await runJS(code);consoleBox.textContent=out;let test=lessonPractice?{ok:true,label:"Lesson example ran. Change an input and predict the new output."}:exercise.test(out);let skill=currentEditor==='sql'?'SQL':currentEditor==='javascript'?'Systems':/ALGORITHMS/.test(exercise.prompt)?'Algorithms':/STATISTICS/.test(exercise.prompt)?'Statistics':/TRADING/.test(exercise.prompt)?'Microstructure':/COST/.test(exercise.prompt)?'Research':/RISK/.test(exercise.prompt)?'Research':'Python';if(!lessonPractice){window.learningRecordCoding?.(exercise.name,skill,test.ok);if(test.ok&&!state.codingCompleted.includes(`${currentEditor}:${exercise.name}`)){state.codingCompleted.push(`${currentEditor}:${exercise.name}`);save()}renderStudioProgress()}testBox.innerHTML=`<span class="section-kicker">CHECK YOUR THINKING</span><div class="test-row ${test.ok?'':'failed'}"><span>${test.ok?'✓':'↻'}</span><b>${test.ok?'Nice work.':'Keep exploring.'}</b></div><p>${test.ok?test.label:'Compare your output with the task, then adjust the code and run it again.'}</p>`;status.innerHTML=`<span class="status-dot"></span> Finished · ${out.split('\n').length} line(s)`;if(!sessionCounted){sessionCounted=true;state.sessions++;state.minutes+=10;setActivityDay();state.todayMinutes+=10;save();setTimeout(()=>{sessionCounted=false},1000)}showToast(test.ok?'Exercise check passed.':'Code ran; keep examining the result.')}catch(e){let failedExercise=exercises[currentEditor]?.[selectedEditors[currentEditor]];if(!lessonPractice&&failedExercise&&!String(e.message||e).includes('runtime')&&!String(e.message||e).includes('sandbox')){let skill=currentEditor==='sql'?'SQL':currentEditor==='javascript'?'Systems':/ALGORITHMS/.test(failedExercise.prompt)?'Algorithms':/STATISTICS/.test(failedExercise.prompt)?'Statistics':/TRADING/.test(failedExercise.prompt)?'Microstructure':/COST/.test(failedExercise.prompt)?'Research':/RISK/.test(failedExercise.prompt)?'Research':'Python';window.learningRecordCoding?.(failedExercise.name,skill,false)}consoleBox.innerHTML=`<span class="console-error">${escapeHTML(e.message||String(e))}</span>`;status.innerHTML='<span class="status-dot" style="background:var(--danger)"></span> Needs a closer look';testBox.innerHTML='<span class="section-kicker">CHECK YOUR THINKING</span><p>Read the error closely. It often points to the exact place where the program got stuck.</p>'}finally{btn.disabled=false;btn.innerHTML='<span>▶</span> Run code'}}
function submitScenario(){const fb=$('#scenario-feedback');if(!scenarioChoice){showToast('Choose the next step you would take.');return}let ok=scenarioChoice==='b';$$('.choice').forEach(c=>{c.classList.toggle('correct',c.dataset.choice==='b');c.classList.toggle('incorrect',c.dataset.choice===scenarioChoice&&!ok)});fb.classList.add('show');fb.innerHTML=ok?'<strong>Good research instinct.</strong> A promising imbalance is a hypothesis to test. Historical predictive power, realistic fills and slippage, regime differences, and a clear invalidation rule make the decision more informed. Keep in mind that no checklist guarantees a profitable trade.':'<strong>Consider what you know and what you do not.</strong> A displayed imbalance alone neither guarantees a fill nor predicts what happens next. Test the historical signal, estimate execution costs, and decide what evidence would invalidate your thesis before committing capital.';$('#scenario-submit').textContent='Decision reviewed ✓';if(!state.scenario){state.scenario='completed';state.recall++;state.sessions++;state.minutes+=15;setActivityDay();state.todayMinutes+=15;save()}showToast(ok?'Scenario reviewed · the evidence matters.':'Scenario reviewed · a useful question to revisit.')}
const tutorData={tutor:{title:'Socratic tutor',subtitle:'A nudge to help you find your own answer',heading:'Let’s start with what you notice.',intro:'Choose a prompt for a quick offline guide, or send your attempt to the research coach for a contextual response.',prompts:[['python','I am stuck on a Python problem.'],['stats','Help me reason about uncertainty.'],['costs','How should I think about trading costs?']]},reviewer:{title:'Research reviewer',subtitle:'A perspective to pressure-test your reasoning',heading:'Make the evidence earn your confidence.',intro:'Choose a quick review checklist, or send your work to the research coach for a contextual critique.',prompts:[['bias','What might be leaking into my backtest?'],['data','What should I inspect in my data?'],['evidence','How strong is this result, really?']]},planner:{title:'Study planner',subtitle:'A focused next step based on your progress',heading:'What would move you forward today?',intro:'Choose a short planning guide, or ask the research coach to make a plan around your progress.',prompts:[['next','What is a sensible next step?'],['routine','Help me plan a practice session.'],['review','What should I revisit?']]}};const coaching={python:['Reduce the problem to the smallest input that still shows the issue.','Trace one value through each step and compare the expected value with the actual value.','Check an empty input, a one-item input, and a repeated value.','Write what you tried below, then ask the research coach to inspect it with the current lesson and code.'],stats:['State the population and sample before interpreting the estimate.','Check sample size, dependence, and uncertainty—not only the point estimate.','Ask whether a different period or reasonable assumption changes the conclusion.','Write your interpretation below to get a contextual review.'],costs:['Separate spread, fees, slippage, and market impact.','Check whether the assumed fill price and order size are plausible.','Stress the cost estimate and see whether the result survives.','Write your assumptions below to get a contextual review.'],bias:['Record when every input becomes knowable.','Check timestamps, universe selection, normalization, and overlapping labels.','Reserve an untouched period and avoid tuning against it.','Write your suspected leakage path below to get a contextual review.'],data:['Check missing timestamps, duplicate rows, stale prices, and units.','Confirm each table’s row grain and inspect join keys before joining.','Trace one observation to its source and availability date.','Write what you found below to get a contextual review.'],evidence:['Separate the claim from the evidence supporting it.','Record how many variations you tried and quantify uncertainty.','Check an untouched period and a plausible baseline.','Write your result below to get a contextual critique.'],next:['Continue with the next unfinished lesson: '+(nextLesson()?.title||'review your research note')+'.','Choose one coding or assessment task that applies the idea.','Write down one assumption and what evidence would change your mind.','Ask the research coach to adapt this plan to your current progress.'],routine:['Choose one question, one exercise, and one concrete output.','Predict the result before running code.','Reserve the final minutes to explain a surprise and plan a delayed review.','Ask the research coach to adapt this session to your current weak areas.'],review:['Recall the idea before reopening the lesson.','Explain it in your own words and compare against the example.','Try a changed input to check whether the idea transfers.','Ask the research coach to choose a review based on your progress.']};function openTutor(agent='tutor'){let data=tutorData[agent]||tutorData.tutor;$('#tutor-title').textContent=data.title;$('#tutor-subtitle').textContent=data.subtitle;$('#tutor-prompt-title').textContent=data.heading;$('#tutor-prompt').textContent=data.intro;$('#tutor-response').classList.remove('show');$('#tutor-prompts').innerHTML=data.prompts.map(([id,label])=>`<button class="tutor-prompt-button" data-coaching="${id}"><span>↗</span>${label}</button>`).join('');$$('[data-coaching]').forEach(b=>b.addEventListener('click',()=>{let ideas=coaching[b.dataset.coaching]||coaching.next;let response=$('#tutor-response');response.innerHTML=`<h3>A quick offline guide</h3><p>Start with these checks, then add your thinking below for a contextual coach review.</p><ol>${ideas.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol><label class="tutor-attempt-label">What have you tried? (optional)<textarea class="tutor-attempt" rows="3" placeholder="Your approach, expected result, and what happened…"></textarea></label><button type="button" class="button-primary tutor-ask-button" data-tutor-ask="${b.dataset.coaching}">Ask research coach ↗</button><p class="tutor-mode-note">Offline guide above is rule-based. The research coach can use installed/local or configured remote models; without a model it will explain the fallback it used.</p>`;response.classList.add('show');let ask=$('[data-tutor-ask]');ask.addEventListener('click',()=>{let title=$('#tutor-title').textContent||'Socratic tutor',role=title.toLowerCase().includes('reviewer')?'reviewer':title.toLowerCase().includes('planner')?'planner':'tutor',code=$('#code-input')?.value||'',brief=$('#exercise-brief')?.innerText||'',lesson=$('#lesson-content')?.innerText||'',attempt=$('.tutor-attempt')?.value.trim()||'',question=`${b.innerText.trim()}${attempt?'\n\nWhat I have tried or concluded:\n'+attempt:''} Ask Socratic coaching: first respond to my attempt, point out one concrete issue or strength, then ask one focused question and suggest the smallest useful next step. Do not give away the full solution.`;document.dispatchEvent(new CustomEvent('fieldnotes:coach',{detail:{agent:role,question,artifact:`Current exercise:\n${brief.slice(0,2500)}\nLesson context:\n${lesson.slice(0,2500)}\nLearner code:\n${code.slice(0,5000)}`}}))})}));$('#tutor-overlay').hidden=false}
function init(){const d=new Date();$('#today-label').textContent=d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}).toUpperCase();$('#date-big').textContent=d.toLocaleDateString(undefined,{month:'long',day:'numeric'});renderProgress();let initial=(location.hash||'#dashboard').slice(1);if(!$('#view-'+initial))initial='dashboard';selectView(initial);setEditor('python');$$('[data-view]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();selectView(el.dataset.view)}));$$('[data-navigate]').forEach(el=>el.addEventListener('click',()=>selectView(el.dataset.navigate)));$$('[data-scenario]').forEach(el=>el.addEventListener('click',()=>{selectView('scenarios');window.scrollTo(0,0)}));$('#resume-learning').addEventListener('click',()=>openLesson(nextLesson().id));$$('[data-goal]').forEach(b=>b.addEventListener('click',()=>{state.goal=Number(b.dataset.goal);save();showToast(`Daily intention updated to ${state.goal} minutes.`)}));$$('.editor-tab').forEach(b=>b.addEventListener('click',()=>setEditor(b.dataset.editor)));$('#exercise-select').addEventListener('change',e=>{selectedEditors[currentEditor]=Number(e.target.value);setEditor(currentEditor)});$('#exercise-previous').addEventListener('click',()=>moveExercise(-1));$('#exercise-next').addEventListener('click',()=>moveExercise(1));$('#reset-code').addEventListener('click',()=>setEditor(currentEditor));$('#run-code').addEventListener('click',runCode);$('#code-input').addEventListener('input',updateLineNums);$('#code-input').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();let start=e.target.selectionStart,end=e.target.selectionEnd;e.target.setRangeText('    ',start,end,'end');updateLineNums()}});$('#scenario-submit').addEventListener('click',submitScenario);$$('.choice').forEach(b=>b.addEventListener('click',()=>{scenarioChoice=b.dataset.choice;$$('.choice').forEach(c=>c.classList.toggle('selected',c===b))}));$('#theme-toggle').addEventListener('click',()=>{document.body.classList.toggle('light-mode');$('#theme-toggle .theme-state').textContent=document.body.classList.contains('light-mode')?'Light':'Dark';localStorage.setItem('fieldnotes-theme',document.body.classList.contains('light-mode')?'light':'dark')});if(localStorage.getItem('fieldnotes-theme')==='light'){$('body').classList.add('light-mode');$('#theme-toggle .theme-state').textContent='Light'}$$('[data-open-tutor]').forEach(b=>b.addEventListener('click',()=>openTutor('tutor')));$$('[data-agent]').forEach(b=>b.addEventListener('click',()=>openTutor(b.dataset.agent)));$$('[data-close-tutor]').forEach(b=>b.addEventListener('click',()=>$('#tutor-overlay').hidden=true));$$('[data-close-lesson]').forEach(b=>b.addEventListener('click',()=>$('#lesson-overlay').hidden=true));document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#lesson-overlay').hidden=true;$('#tutor-overlay').hidden=true;$('#account-overlay').hidden=true;$('#coach-modal').hidden=true}})}init();
window.Fieldnotes={
 get state(){return state},get modules(){return modules},get user(){return accountUser},getState:()=>state,coachConfigured:false,
 save:()=>save(),saveDraft:()=>{let key=accountUser?'fieldnotes-state:'+accountUser.email.toLowerCase():'fieldnotes-state';localStorage.setItem(key,JSON.stringify(state))},saveQuiet:()=>{let key=accountUser?'fieldnotes-state:'+accountUser.email.toLowerCase():'fieldnotes-state';localStorage.setItem(key,JSON.stringify(state));window.dispatchEvent(new CustomEvent('fieldnotes:progress-saved',{detail:{state,account:accountUser}}))},
 applySyncedState:remote=>{if(!remote)return;state={...defaultState,...remote,curriculumVersion:2};let key=accountUser?'fieldnotes-state:'+accountUser.email.toLowerCase():'fieldnotes-state';localStorage.setItem(key,JSON.stringify(state));renderProgress()},
 setAccount:(user,remote,coach)=>{accountUser=user||null;cloudEnabled=!!user;window.Fieldnotes.coachConfigured=!!coach;if(user&&remote)state={...defaultState,...remote,curriculumVersion:2};else state={...defaultState,curriculumVersion:2};let key=user?'fieldnotes-state:'+user.email.toLowerCase():'fieldnotes-state';localStorage.setItem(key,JSON.stringify(state));renderProgress()},
 recordSession:minutes=>{setActivityDay();state.sessions=(state.sessions||0)+1;state.minutes=(state.minutes||0)+Math.max(1,Math.min(240,minutes||5));state.todayMinutes=(state.todayMinutes||0)+Math.max(1,Math.min(240,minutes||5));save()},toast:showToast,navigate:selectView
};
function bindProgressBackup(){const exportButton=$('#export-progress'),importButton=$('#import-progress-button'),file=$('#import-progress-file'),status=$('#portability-status');if(!exportButton||!importButton||!file)return;exportButton.addEventListener('click',()=>{try{const data={format:'fieldnotes-progress',version:1,exportedAt:new Date().toISOString(),progress:window.Fieldnotes.getState()};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`fieldnotes-progress-${new Date().toISOString().slice(0,10)}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Backup downloaded. Keep it somewhere private; it can contain your notes and work.'}catch(error){status.textContent='Could not create a backup in this browser. Try again or use another browser.'}});importButton.addEventListener('click',()=>file.click());file.addEventListener('change',async()=>{const backup=file.files?.[0];file.value='';if(!backup)return;if(backup.size>5*1024*1024){status.textContent='This backup is larger than 5 MB and was not imported.';return}try{const parsed=JSON.parse(await backup.text()),candidate=parsed?.format==='fieldnotes-progress'?parsed.progress:parsed;if(!candidate||typeof candidate!=='object'||Array.isArray(candidate)||!Array.isArray(candidate.done)||typeof candidate.goal!=='number'||!Number.isFinite(candidate.goal)||candidate.goal<5||candidate.goal>240)throw new Error('The file does not contain a valid learning record.');for(const key of ['attempts','reviews','skills','projects','interviewNotes','scenarioNotes'])if(candidate[key]!=null&&(typeof candidate[key]!=='object'||Array.isArray(candidate[key])))throw new Error('A progress section has an invalid format.');for(const key of Object.keys(candidate))if(key==='__proto__'||key==='constructor'||key==='prototype')throw new Error('The backup contains an unsupported field.');const confirmed=window.confirm('Import this backup and replace the progress saved in this browser? Export the current progress first if you may need it.');if(!confirmed)return;state={...defaultState,...candidate,curriculumVersion:2};for(const key of ['attempts','reviews','skills','projects','interviewNotes','scenarioNotes'])state[key]={...(candidate[key]||{})};state.done=[...new Set(candidate.done.filter(id=>typeof id==='string'&&getLesson(id)))];save();status.textContent=`Backup imported. Restored ${state.done.length} completed lessons and your saved practice record.`;showToast('Learning backup restored on this device.')}catch(error){status.textContent=error.message==='The file does not contain a valid learning record.'||error.message.startsWith('A progress section')||error.message.startsWith('The backup contains')?error.message:'Could not read this backup. Choose a Fieldnotes JSON export.'}})}bindProgressBackup();
